from collections import deque

class Solution(object):
    def solve(self, data):
        tokens = deque(data['tokens'])

        stack = []
        while tokens:
            token = tokens.popleft()
            if token.isdigit():
                stack.append(int(token))
            else:
                right = stack.pop()
                left = stack.pop()

                if token == '+':
                    stack.append(left + right)
                elif token == '-':
                    stack.append(left - right)
                elif token == '*':
                    stack.append(left * right)
                elif token == '/':
                    stack.append(int(left / right)) # Truncate towards zero

        return stack[0]

